            <div class="meta-row">
              <span class="meta-label">File size</span>
              <span class="meta-value">8.4 MB</span>
            </div>
            <div class="meta-row">
              <span class="meta-label">Added</span>
              <span class="meta-value">May 2, 2026</span>
